// Compiled JavaScript from TypeScript for home page functionality
// This file addresses shortcut button issues and provides robust functionality

class HomePageManager {
    constructor() {
        this.cart = [];
        this.total = 0;
        this.allProducts = [];
        this.modalOpen = false;
        this.initializePage();
    }

    initializePage() {
        console.log('🚀 TypeScript: Initializing home page...');
        
        // Wait for DOM to be fully loaded
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => this.setupEventListeners());
        } else {
            this.setupEventListeners();
        }
    }

    setupEventListeners() {
        console.log('🔧 TypeScript: Setting up event listeners...');
        
        // Setup shortcut button with multiple approaches
        this.setupShortcutButton();
        
        // Setup search functionality
        this.setupSearch();
        
        // Setup keyboard shortcuts
        this.setupKeyboardShortcuts();
        
        // Setup barcode scanner
        this.setupBarcodeScanner();
        
        // Setup mobile menu
        this.setupMobileMenu();
        
        // Setup modal click outside
        this.setupModalClickOutside();
        
        console.log('✅ TypeScript: All event listeners setup complete');
    }

    setupShortcutButton() {
        const shortcutsButton = document.querySelector('.shortcut-help');
        
        if (!shortcutsButton) {
            console.log('ℹ️ TypeScript: Shortcut help text found (no button functionality needed)');
            return;
        }

        console.log('🎯 TypeScript: Shortcut help element found');
    }

    ensureButtonContent(button) {
        // Ensure button has proper text content
        if (!button.textContent || button.textContent.trim() === '') {
            button.innerHTML = '<i class="fa-solid fa-circle-info"></i> Shortcuts';
        }
        
        // Ensure button has proper attributes
        button.setAttribute('role', 'button');
        button.setAttribute('aria-label', 'Toggle keyboard shortcuts modal');
        button.setAttribute('title', 'View keyboard shortcuts');
    }

    forceButtonStyles(button) {
        // Force critical CSS styles via JavaScript
        const criticalStyles = {
            'display': 'flex',
            'align-items': 'center',
            'gap': '0.5rem',
            'padding': '1rem 2rem',
            'border': 'none',
            'border-radius': '0.75rem',
            'font-size': '1rem',
            'font-weight': '600',
            'cursor': 'pointer',
            'pointer-events': 'auto',
            'z-index': '9999',
            'position': 'relative',
            'background': 'linear-gradient(135deg, #9333ea, #7c3aed)',
            'color': 'white',
            'min-width': '150px',
            'justify-content': 'center',
            'transition': 'all 0.3s ease',
            'box-shadow': '0 4px 15px rgba(0, 0, 0, 0.1)',
            'visibility': 'visible',
            'opacity': '1'
        };

        Object.entries(criticalStyles).forEach(([property, value]) => {
            button.style[property] = value;
        });
    }

    addVisualFeedback(button) {
        // Add scale animation for visual feedback
        button.style.transform = 'scale(0.95)';
        setTimeout(() => {
            button.style.transform = 'translateY(-2px)';
        }, 100);
    }

    retryShortcutButtonSetup() {
        console.log('⏰ TypeScript: Retrying shortcut button setup...');
        setTimeout(() => {
            const retryButton = document.getElementById('shortcuts-btn');
            if (retryButton) {
                console.log('✅ TypeScript: Button found on retry, setting up events');
                this.setupShortcutButton();
            } else {
                console.error('❌ TypeScript: Button still not found after retry');
                this.createFallbackButton();
            }
        }, 2000);
    }

    createFallbackButton() {
        console.log('🔧 TypeScript: Creating fallback shortcut button...');
        
        const actionButtons = document.querySelector('.action-buttons');
        if (actionButtons) {
            const fallbackButton = document.createElement('button');
            fallbackButton.id = 'shortcuts-btn-fallback';
            fallbackButton.className = 'action-btn shortcuts-btn';
            fallbackButton.innerHTML = '<i class="fa-solid fa-circle-info"></i> Shortcuts';
            fallbackButton.setAttribute('onclick', 'homePageManager.toggleShortcuts()');
            
            // Apply styles
            this.forceButtonStyles(fallbackButton);
            
            actionButtons.appendChild(fallbackButton);
            
            // Setup event listeners for fallback button
            fallbackButton.addEventListener('click', (e) => {
                e.preventDefault();
                this.toggleShortcuts();
            });
            
            console.log('✅ TypeScript: Fallback button created and added to page');
        }
    }

    toggleShortcuts() {
        const modal = document.getElementById('shortcuts-modal');
        console.log('🔄 TypeScript: Toggle shortcuts called, modal:', modal);
        
        if (!modal) {
            console.error('❌ TypeScript: Shortcuts modal not found');
            this.showNotification('Error: Shortcuts modal not found', 'error');
            return;
        }

        this.modalOpen = !this.modalOpen;
        
        if (this.modalOpen) {
            modal.style.display = 'flex';
            document.body.style.overflow = 'hidden';
            console.log('📖 TypeScript: Modal opened');
            this.showNotification('Shortcuts modal opened', 'success');
        } else {
            modal.style.display = 'none';
            document.body.style.overflow = '';
            console.log('📕 TypeScript: Modal closed');
        }
    }

    setupSearch() {
        const searchInput = document.getElementById('product-search');
        const clearButton = document.getElementById('clear-search');
        const productsGrid = document.getElementById('products-grid');
        
        if (!searchInput || !clearButton || !productsGrid) {
            console.warn('⚠️ TypeScript: Search elements not found');
            return;
        }

        // Store all products
        const productCards = productsGrid.querySelectorAll('.product-card');
        this.allProducts = Array.from(productCards).map(card => ({
            element: card,
            name: card.querySelector('h3')?.textContent?.toLowerCase() || '',
            price: card.querySelector('.product-price')?.textContent || '',
            regular_price: 0,
            is_currently_on_sale: false,
            category: card.querySelector('.product-category')?.textContent || ''
        }));

        // Search event listener
        searchInput.addEventListener('input', () => {
            const searchTerm = searchInput.value.toLowerCase().trim();
            
            if (searchTerm) {
                clearButton.style.display = 'block';
            } else {
                clearButton.style.display = 'none';
            }
            
            this.filterProducts(searchTerm);
        });

        // Clear search event listener
        clearButton.addEventListener('click', () => {
            searchInput.value = '';
            clearButton.style.display = 'none';
            this.filterProducts('');
            searchInput.focus();
        });

        // Escape key to clear search
        searchInput.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                searchInput.value = '';
                clearButton.style.display = 'none';
                this.filterProducts('');
            }
        });
    }

    filterProducts(searchTerm) {
        const productsGrid = document.getElementById('products-grid');
        if (!productsGrid) return;

        let hasResults = false;
        
        this.allProducts.forEach(product => {
            const matchesSearch = product.name.includes(searchTerm) || 
                                 product.category.toLowerCase().includes(searchTerm);
            
            if (matchesSearch) {
                product.element.style.display = '';
                hasResults = true;
            } else {
                product.element.style.display = 'none';
            }
        });

        // Show/hide no results message
        let noResultsMsg = productsGrid.querySelector('.no-results');
        if (!hasResults) {
            if (!noResultsMsg) {
                noResultsMsg = document.createElement('div');
                noResultsMsg.className = 'no-results';
                noResultsMsg.innerHTML = `
                    <div style="text-align: center; padding: 2rem; color: #718096;">
                        <i class="fas fa-search" style="font-size: 2rem; margin-bottom: 1rem; opacity: 0.5;"></i>
                        <p>No products found matching "${searchTerm}"</p>
                    </div>
                `;
                productsGrid.appendChild(noResultsMsg);
            }
        } else if (noResultsMsg) {
            noResultsMsg.remove();
        }
    }

    setupKeyboardShortcuts() {
        document.addEventListener('keydown', (e) => {
            // Don't trigger shortcuts when typing in input fields
            if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) {
                return;
            }
            
            // Ctrl + C: Clear Cart
            if (e.ctrlKey && e.key === 'c') {
                e.preventDefault();
                this.clearCart();
            }
            
            // Ctrl + S: Save Order
            if (e.ctrlKey && e.key === 's') {
                e.preventDefault();
                this.saveOrder();
            }
            
            // Ctrl + F: Focus Search
            if (e.ctrlKey && e.key === 'f') {
                e.preventDefault();
                const searchInput = document.getElementById('product-search');
                if (searchInput) searchInput.focus();
            }
            
            // Ctrl + B: Toggle Barcode Scanner
            if (e.ctrlKey && e.key === 'b') {
                e.preventDefault();
                this.toggleBarcodeScan();
            }
            
            // Escape: Close modals and clear search
            if (e.key === 'Escape') {
                if (this.modalOpen) {
                    this.toggleShortcuts();
                } else {
                    const searchInput = document.getElementById('product-search');
                    if (searchInput && searchInput.value) {
                        searchInput.value = '';
                        this.filterProducts('');
                        const clearButton = document.getElementById('clear-search');
                        if (clearButton) clearButton.style.display = 'none';
                    }
                }
            }
        });
    }

    setupBarcodeScanner() {
        const barcodeInput = document.getElementById('barcode-scan-input');
        const barcodeButton = document.querySelector('.btn-scan-barcode');
        
        if (!barcodeInput || !barcodeButton) {
            console.warn('⚠️ TypeScript: Barcode scanner elements not found');
            return;
        }

        // Button click/touch events
        barcodeButton.addEventListener('click', (e) => {
            e.preventDefault();
            this.toggleBarcodeScan();
        });
        
        barcodeButton.addEventListener('touchstart', (e) => {
            e.preventDefault();
            barcodeButton.classList.add('touch-active');
        });
        
        barcodeButton.addEventListener('touchend', (e) => {
            e.preventDefault();
            barcodeButton.classList.remove('touch-active');
            this.toggleBarcodeScan();
        });

        // Input events
        barcodeInput.addEventListener('focus', () => {
            this.updateScanStatus('Ready to scan', 'ready');
        });
        
        barcodeInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                this.handleBarcodeScan(e);
            }
        });
        
        barcodeInput.addEventListener('input', (e) => {
            this.handleBarcodeInput(e);
        });
    }

    toggleBarcodeScan() {
        const panel = document.getElementById('barcode-scan-panel');
        const input = document.getElementById('barcode-scan-input');
        const button = document.querySelector('.btn-scan-barcode');
        
        if (!panel || !input || !button) return;
        
        if (panel.style.display === 'none' || !panel.style.display) {
            panel.style.display = 'flex';
            panel.style.flexDirection = 'column';
            panel.style.gap = '0.75rem';
            button.classList.add('active');
            
            setTimeout(() => {
                input.focus();
                input.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 100);
            
            this.updateScanStatus('Ready to scan', 'ready');
        } else {
            panel.style.display = 'none';
            input.value = '';
            button.classList.remove('active');
        }
    }

    handleBarcodeScan(event) {
        const input = event.target;
        const barcode = input.value.trim();
        
        if (event.key === 'Enter' || event.key === 'Go') {
            event.preventDefault();
            if (barcode) {
                this.findAndAddProductByBarcode(barcode);
            }
        } else if (barcode) {
            this.updateScanStatus('Scanning...', 'scanning');
        }
    }

    handleBarcodeInput(event) {
        const input = event.target;
        const barcode = input.value.trim();
        
        if (barcode.length >= 8) {
            if (barcode.length >= 12 && barcode.length <= 13) {
                setTimeout(() => {
                    if (input.value.trim() === barcode) {
                        this.findAndAddProductByBarcode(barcode);
                    }
                }, 500);
            }
        } else if (barcode) {
            this.updateScanStatus('Scanning...', 'scanning');
        }
    }

    async findAndAddProductByBarcode(barcode) {
        this.updateScanStatus('Searching...', 'scanning');
        
        try {
            const csrfToken = document.querySelector('[name=csrfmiddlewaretoken]');
            const headers = {
                'Content-Type': 'application/json',
                'X-Requested-With': 'XMLHttpRequest'
            };
            
            if (csrfToken) {
                headers['X-CSRFToken'] = csrfToken.content;
            }
            
            const response = await fetch(`/api/get_product_by_barcode/?barcode=${encodeURIComponent(barcode)}`, {
                method: 'GET',
                headers
            });
            
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            
            const data = await response.json();
            
            if (data.status === 'success') {
                const product = data.product;
                this.addToCart(
                    product.name,
                    parseFloat(product.price),
                    product.is_currently_on_sale,
                    parseFloat(product.regular_price),
                    product.sale_price ? parseFloat(product.sale_price) : null
                );
                this.updateScanStatus('Product added to cart!', 'success');
                
                const input = document.getElementById('barcode-scan-input');
                if (input) input.value = '';
                
                setTimeout(() => {
                    this.toggleBarcodeScan();
                }, 1500);
            } else {
                this.updateScanStatus(data.message || 'Product not found', 'error');
                setTimeout(() => {
                    this.updateScanStatus('Ready to scan', 'ready');
                    const input = document.getElementById('barcode-scan-input');
                    if (input) {
                        input.value = '';
                        input.focus();
                    }
                }, 2000);
            }
        } catch (error) {
            console.error('Error fetching product:', error);
            this.updateScanStatus('Error scanning barcode', 'error');
            setTimeout(() => {
                this.updateScanStatus('Ready to scan', 'ready');
                const input = document.getElementById('barcode-scan-input');
                if (input) {
                    input.value = '';
                    input.focus();
                }
            }, 2000);
        }
    }

    updateScanStatus(message, status) {
        const statusDiv = document.getElementById('scan-status');
        if (!statusDiv) return;
        
        const iconMap = {
            'ready': 'camera',
            'scanning': 'spinner fa-spin',
            'success': 'check-circle',
            'error': 'exclamation-triangle'
        };
        
        statusDiv.innerHTML = `<i class="fas fa-${iconMap[status] || 'camera'}"></i> ${message}`;
        statusDiv.className = `scan-status ${status}`;
    }

    setupMobileMenu() {
        const mobileMenuToggle = document.querySelector('.mobile-menu-toggle');
        const navMenu = document.querySelector('.nav-menu');
        
        if (!mobileMenuToggle || !navMenu) return;

        mobileMenuToggle.addEventListener('click', () => {
            navMenu.classList.toggle('active');
        });
        
        // Close menu when clicking outside
        document.addEventListener('click', (e) => {
            if (!mobileMenuToggle?.contains(e.target) && !navMenu?.contains(e.target)) {
                navMenu.classList.remove('active');
            }
        });
    }

    setupModalClickOutside() {
        document.addEventListener('click', (e) => {
            const shortcutsModal = document.getElementById('shortcuts-modal');
            if (shortcutsModal && this.modalOpen) {
                const modalContent = shortcutsModal.querySelector('.shortcuts-content');
                const shortcutsButton = document.getElementById('shortcuts-btn');
                
                if (!modalContent?.contains(e.target) && 
                    e.target !== shortcutsButton && 
                    !shortcutsButton?.contains(e.target)) {
                    this.toggleShortcuts();
                }
            }
        });
    }

    showNotification(message, type) {
        // Create notification element
        const notification = document.createElement('div');
        notification.className = `notification notification-${type}`;
        notification.innerHTML = `
            <i class="fas fa-${this.getNotificationIcon(type)}"></i>
            <span>${message}</span>
        `;
        
        // Style notification
        Object.assign(notification.style, {
            position: 'fixed',
            top: '20px',
            right: '20px',
            padding: '1rem 1.5rem',
            borderRadius: '0.5rem',
            color: 'white',
            fontWeight: '600',
            zIndex: '10001',
            opacity: '0',
            transform: 'translateX(100%)',
            transition: 'all 0.3s ease'
        });
        
        // Set background color based on type
        const bgColors = {
            success: '#10b981',
            error: '#ef4444',
            warning: '#f59e0b',
            info: '#3b82f6'
        };
        notification.style.background = bgColors[type] || bgColors.info;
        
        document.body.appendChild(notification);
        
        // Animate in
        setTimeout(() => {
            notification.style.opacity = '1';
            notification.style.transform = 'translateX(0)';
        }, 100);
        
        // Remove after 3 seconds
        setTimeout(() => {
            notification.style.opacity = '0';
            notification.style.transform = 'translateX(100%)';
            setTimeout(() => {
                if (notification.parentNode) {
                    notification.parentNode.removeChild(notification);
                }
            }, 300);
        }, 3000);
    }

    getNotificationIcon(type) {
        const icons = {
            success: 'check-circle',
            error: 'exclamation-triangle',
            warning: 'exclamation-circle',
            info: 'info-circle'
        };
        return icons[type] || 'info-circle';
    }

    // Cart Management Methods
    addToCart(product, price, isOnSale = false, regularPrice = null, salePrice = null) {
        const existingItem = this.cart.find(item => item.product === product);
        if (existingItem) {
            existingItem.quantity += 1;
        } else {
            this.cart.push({ 
                product, 
                price, 
                regularPrice: regularPrice || price,
                salePrice: salePrice || undefined,
                isOnSale,
                quantity: 1 
            });
        }
        this.total += price;
        this.updateCart();
    }

    removeFromCart(product, price) {
        const existingItem = this.cart.find(item => item.product === product);
        if (existingItem) {
            if (existingItem.quantity > 1) {
                existingItem.quantity -= 1;
                this.total -= price;
            } else {
                // Remove item completely if quantity is 1
                const index = this.cart.indexOf(existingItem);
                this.cart.splice(index, 1);
                this.total -= price;
            }
            this.updateCart();
        }
    }

    cancelCartItem(product) {
        const existingItem = this.cart.find(item => item.product === product);
        if (existingItem) {
            // Remove item completely regardless of quantity
            const index = this.cart.indexOf(existingItem);
            this.total -= (existingItem.price * existingItem.quantity);
            this.cart.splice(index, 1);
            this.updateCart();
            this.showNotification(`${product} removed from cart`, 'info');
        }
    }

    updateCart() {
        const cartItems = document.getElementById('cart-items');
        if (!cartItems) return;

        cartItems.innerHTML = '';
        this.cart.forEach(item => {
            const div = document.createElement('div');
            div.className = 'cart-item';
            
            // Build price display based on whether item is on sale
            let priceDisplay = '';
            if (item.isOnSale && item.regularPrice && item.salePrice) {
                priceDisplay = `
                    <div class="cart-item-pricing">
                        <span class="cart-item-sale-price">R${(item.price * item.quantity).toFixed(2)}</span>
                        <span class="cart-item-original-price">R${(item.regularPrice * item.quantity).toFixed(2)}</span>
                    </div>
                `;
            } else {
                priceDisplay = `<span>R${(item.price * item.quantity).toFixed(2)}</span>`;
            }
            
            div.innerHTML = `
                <div class="cart-item-info">
                    <span class="cart-item-name">${item.product} x${item.quantity}</span>
                    ${item.isOnSale ? '<span class="cart-item-sale-badge">SALE</span>' : ''}
                </div>
                ${priceDisplay}
                <div class="cart-item-actions">
                    <button class="remove-btn" onclick="homePageManager.removeFromCart('${item.product}', ${item.price})">-</button>
                    <button class="cancel-btn" onclick="homePageManager.cancelCartItem('${item.product}')" title="Remove item from cart">⛔</button>
                </div>
            `;
            cartItems.appendChild(div);
        });
        
        const totalElement = document.getElementById('total');
        if (totalElement) {
            totalElement.innerHTML = 'R' + this.total.toFixed(2);
        }
        
        // Recalculate change when cart is updated
        this.calculateChange();
    }

    calculateChange() {
        const cashReceivedElement = document.getElementById('cash-received');
        const changeDisplay = document.getElementById('change-display');
        const changeAmount = document.getElementById('change-amount');
        
        if (!cashReceivedElement || !changeDisplay || !changeAmount) return;
        
        const cashReceived = parseFloat(cashReceivedElement.value) || 0;
        
        if (cashReceived > 0 && this.total > 0) {
            const change = cashReceived - this.total;
            changeDisplay.style.display = 'block';
            changeAmount.textContent = change.toFixed(2);
            
            // Add visual feedback for change amount
            if (change >= 0) {
                changeDisplay.className = 'change-display positive';
            } else {
                changeDisplay.className = 'change-display negative';
            }
        } else {
            changeDisplay.style.display = 'none';
        }
    }

    clearCart() {
        this.cart = [];
        this.total = 0;
        
        // Clear all form fields
        const cashReceivedElement = document.getElementById('cash-received');
        const customerNameElement = document.getElementById('customer-name');
        const customerPhoneElement = document.getElementById('customer-phone');
        const changeDisplay = document.getElementById('change-display');
        
        if (cashReceivedElement) cashReceivedElement.value = '';
        if (customerNameElement) customerNameElement.value = '';
        if (customerPhoneElement) customerPhoneElement.value = '';
        if (changeDisplay) changeDisplay.style.display = 'none';
        
        this.updateCart();
        this.showNotification('Cart cleared', 'info');
    }

    async saveOrder() {
        const customerNameElement = document.getElementById('customer-name');
        const customerPhoneElement = document.getElementById('customer-phone');
        
        if (!customerNameElement || !customerPhoneElement) {
            this.showNotification('Customer form elements not found', 'error');
            return;
        }
        
        const customerName = customerNameElement.value.trim();
        const customerPhone = customerPhoneElement.value.trim();
        
        // Validate customer information
        if (!customerName || !customerPhone) {
            this.showNotification('Customer name and phone number are required', 'error');
            if (!customerName) {
                customerNameElement.focus();
            } else {
                customerPhoneElement.focus();
            }
            return;
        }
        
        // Validate phone number format
        const phoneRegex = /^[0-9]{10,15}$/;
        if (!phoneRegex.test(customerPhone)) {
            this.showNotification('Please enter a valid phone number (10-15 digits)', 'error');
            customerPhoneElement.focus();
            return;
        }
        
        // Get CSRF token
        const csrfToken = document.querySelector('[name=csrfmiddlewaretoken]');
        if (!csrfToken) {
            this.showNotification('Security token not found. Please refresh page.', 'error');
            return;
        }
        
        try {
            const response = await fetch('/save_order/', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRFToken': csrfToken.value
                },
                body: JSON.stringify({
                    customer_name: customerName,
                    customer_phone: customerPhone,
                    items: this.cart,
                    total_amount: this.total
                })
            });
            
            const data = await response.json();
            console.log('Save order response:', data);
            
            if (data.success) {
                this.showNotification('Order saved successfully!', 'success');
                this.clearCart();
            } else {
                this.showNotification('Failed to save order: ' + (data.error || 'Unknown error'), 'error');
            }
        } catch (error) {
            console.error('Error:', error);
            this.showNotification('An error occurred while saving order: ' + error.message, 'error');
        }
    }

    async checkoutOrder() {
        if (this.cart.length === 0) {
            this.showNotification('Cart is empty. Add items before checkout.', 'error');
            return;
        }
        
        const customerNameElement = document.getElementById('customer-name');
        const customerPhoneElement = document.getElementById('customer-phone');
        const cashReceivedElement = document.getElementById('cash-received');
        
        if (!customerNameElement || !customerPhoneElement || !cashReceivedElement) {
            this.showNotification('Form elements not found', 'error');
            return;
        }
        
        const customerName = customerNameElement.value.trim();
        const customerPhone = customerPhoneElement.value.trim();
        const cashReceived = parseFloat(cashReceivedElement.value) || 0;
        
        // Validate customer information
        if (!customerName || !customerPhone) {
            this.showNotification('Customer name and phone number are required to complete order.', 'error');
            if (!customerName) {
                customerNameElement.focus();
            } else {
                customerPhoneElement.focus();
            }
            return;
        }
        
        // Validate phone number format
        const phoneRegex = /^[0-9]{10,15}$/;
        if (!phoneRegex.test(customerPhone)) {
            this.showNotification('Please enter a valid phone number (10-15 digits)', 'error');
            customerPhoneElement.focus();
            return;
        }
        
        // Validate payment
        if (cashReceived < this.total) {
            this.showNotification(`Insufficient payment. Customer needs to pay at least R${this.total.toFixed(2)}`, 'error');
            cashReceivedElement.focus();
            return;
        }
        
        const changeGiven = cashReceived - this.total;
        
        // Get CSRF token
        const csrfToken = document.querySelector('[name=csrfmiddlewaretoken]');
        if (!csrfToken) {
            this.showNotification('Security token not found. Please refresh page.', 'error');
            return;
        }
        
        try {
            const response = await fetch('/checkout_order/', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-CSRFToken': csrfToken.value
                },
                body: JSON.stringify({
                    customer_name: customerName,
                    customer_phone: customerPhone,
                    items: this.cart,
                    total: this.total,
                    cashReceived: cashReceived,
                    changeGiven: changeGiven
                })
            });
            
            console.log('Response status:', response.status);
            const data = await response.json();
            console.log('Response data:', data);
            
            if (data.status === 'success') {
                this.showNotification('Order completed successfully!', 'success');
                this.clearCart();
            } else {
                this.showNotification('Failed to complete order: ' + (data.message || 'Unknown error'), 'error');
            }
        } catch (error) {
            console.error('Error:', error);
            this.showNotification('An error occurred while processing order: ' + error.message, 'error');
        }
    }

    // Public method to initialize from global scope
    initialize() {
        console.log('🎯 TypeScript: HomePageManager initialized');
    }
}

// Create global instance
let homePageManager;

// Initialize when DOM is ready
function initializeHomePage() {
    homePageManager = new HomePageManager();
    window.homePageManager = homePageManager; // Make it globally accessible
    
    // Expose key methods for inline event handlers
    window.toggleShortcuts = () => homePageManager.toggleShortcuts();
    window.clearCart = () => homePageManager.clearCart();
    window.saveOrder = () => homePageManager.saveOrder();
    window.checkoutOrder = () => homePageManager.checkoutOrder();
    window.addToCartFromData = (element) => {
        const productName = element.dataset.productName || '';
        const currentPrice = parseFloat(element.dataset.currentPrice || '0');
        const isOnSale = element.dataset.isOnSale === 'true';
        const regularPrice = parseFloat(element.dataset.regularPrice || '0');
        const salePrice = element.dataset.salePrice ? parseFloat(element.dataset.salePrice) : null;
        
        homePageManager.addToCart(productName, currentPrice, isOnSale, regularPrice, salePrice);
    };
    window.toggleBarcodeScan = () => homePageManager.toggleBarcodeScan();
    window.handleBarcodeScan = (event) => homePageManager.handleBarcodeScan(event);
    window.handleBarcodeInput = (event) => homePageManager.handleBarcodeInput(event);
    window.calculateChange = () => homePageManager.calculateChange();
    
    console.log('🌐 TypeScript: Global methods exposed and ready');
}

// Auto-initialize
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeHomePage);
} else {
    initializeHomePage();
}
